const unsigned char *bench_kat(bench_fn fn, size_t len, size_t *out_len)
{
    size_t i;

    for (i = 0; i < sizeof(entries) / sizeof(entries[0]); i++) {
        if (entries[i].fn == fn && entries[i].len == len) {
            *out_len = entries[i].out_len;
            return entries[i].out;
        }
    }
    return NULL;
}
